const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/junitunhandled";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "reject.test.mjs"), [
  "import { it } from 'vitest'",
  "it('passes but leaks a rejection', async () => {",
  "  void Promise.reject(new Error('leaked rejection'))",
  "  await new Promise(resolve => setTimeout(resolve, 50))",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--reporter=junit", "--outputFile=junit.xml"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const file = path.join(dir, "junit.xml");
if (!fs.existsSync(file)) {
  console.error("ERROR: vitest wrote no JUnit report (exit " + r.status + ")");
  process.exit(2);
}
const xml = fs.readFileSync(file, "utf8");
console.log(xml);
const m = xml.match(/<testsuites\b[^>]*\berrors="(\d+)"/);
if (!m) {
  console.error("ERROR: no <testsuites> element with an errors attribute");
  process.exit(2);
}
if (r.status !== 1) {
  console.error("ERROR: expected vitest to exit 1 for the unhandled rejection, got " + r.status);
  process.exit(2);
}
const errors = Number(m[1]);
const hasErrorEl = /<error\b/.test(xml) && xml.includes("leaked rejection");
if (errors >= 1 && hasErrorEl) {
  console.log("PASS: JUnit report counts the unhandled rejection, errors=" + errors);
  process.exit(0);
}
if (errors === 0 && !hasErrorEl) {
  console.error("FAIL: JUnit report has errors=0 and no <error> for the unhandled rejection although vitest exited 1");
  process.exit(1);
}
console.error("ERROR: unexpected report (errors=" + errors + ", error element " + hasErrorEl + ")");
process.exit(2);

